<?php require_once __DIR__.'/../app/bootstrap.php'; if(current_user()) redirect('dashboard.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $u=trim($_POST['username']??''); $e=trim($_POST['email']??'') ?: null; $p=$_POST['password']??''; if(mb_strlen($u)<2||strlen($p)<6){$error='用户名至少2位，密码至少6位';} else { try{$stmt=db()->prepare('INSERT INTO users(username,email,password_hash) VALUES(?,?,?)');$stmt->execute([$u,$e,password_hash($p,PASSWORD_DEFAULT)]);login_user((int)db()->lastInsertId());redirect('dashboard.php');}catch(Throwable $ex){$error='注册失败：用户名或邮箱可能已存在';}} } $title='注册'; ?>
<?php include __DIR__.'/../app/layout/header.php'; ?><div class="auth card"><h2>注册阅心</h2><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><p><label>用户名</label><input name="username" required></p><p><label>邮箱，可选</label><input type="email" name="email"></p><p><label>密码</label><input type="password" name="password" required></p><p><button>注册</button> <a class="btn ghost" href="login.php">返回登录</a></p></form></div><?php include __DIR__.'/../app/layout/footer.php'; ?>
